class Point3D {
    final double x, y, z;
    Point3D(double x, double y, double z) { this.x = x; this.y = y; this.z = z; }
    Point3D translate(double dx, double dy, double dz) { return new Point3D(x+dx, y+dy, z+dz); }
    Point3D scale(double f) { return new Point3D(x*f, y*f, z*f); }
    double distance(Point3D o) { return Math.sqrt(Math.pow(x-o.x,2)+Math.pow(y-o.y,2)+Math.pow(z-o.z,2)); }
}

public static void main(String[] args) {
    Point3D p = new Point3D(1,1,1).translate(2,2,2).scale(2);
    System.out.println(p.x + " " + p.y + " " + p.z);
}

