    void increment() { if (current < maxValue) current++; }
    final boolean isAtMax() { return current == maxValue; }
}
class ExtendedCounter extends SafeCounter { ExtendedCounter(int max) { super(max); } void reset() { current = 0; } }

public static void main(String[] args) {
    ExtendedCounter c = new ExtendedCounter(3);
    c.increment(); c.increment(); c.increment(); c.increment();
    System.out.println(c.isAtMax());
}

