class ImmutableGraph {
    final int[][] adjacencyMatrix; final int nodeCount;
    ImmutableGraph(int[][] matrix) {
        nodeCount = matrix.length;
        adjacencyMatrix = new int[nodeCount][nodeCount];
        for (int i = 0; i < nodeCount; i++) adjacencyMatrix[i] = matrix[i].clone();
    }
    ImmutableGraph addEdge(int from, int to) {
        int[][] copy = new int[nodeCount][nodeCount];
        for (int i = 0; i < nodeCount; i++) copy[i] = adjacencyMatrix[i].clone();
        copy[from][to] = 1;
        return new ImmutableGraph(copy);
    }
}

public static void main(String[] args) {
    ImmutableGraph g = new ImmutableGraph(new int[3][3]);
    ImmutableGraph g2 = g.addEdge(0, 1);
    System.out.println(g.adjacencyMatrix[0][1] + " vs " + g2.adjacencyMatrix[0][1]);
}

