interface MathOp { int square(int n); }
class FastMath implements MathOp { public final int square(int n) { return n * n; } }
class SlowMath implements MathOp { public int square(int n) { return n * n; } }

public static void main(String[] args) {
    MathOp fast = new FastMath(), slow = new SlowMath();
    long t1 = System.nanoTime();
    for (int i = 0; i < 10_000_000; i++) fast.square(i);
    long time1 = System.nanoTime() - t1;
    long t2 = System.nanoTime();
    for (int i = 0; i < 10_000_000; i++) slow.square(i);
    long time2 = System.nanoTime() - t2;
    System.out.println("final: " + time1 + "ns, zwykla: " + time2 + "ns");
    // JIT (zwlaszcza po 'rozgrzaniu' - wielokrotnym wywolaniu) czesto eliminuje roznice,
    // bo devirtualizuje wywolania monomorficzne niezaleznie od final
}

